using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishAudit{
 public static object RestoreAfterOwnPlay(){if(Application.isPlaying)throw new Exception("Stop play first");var s=SceneManager.GetActiveScene();if(!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Unexpected scene");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(s.path);return Run();}
 public static object Run(){string root=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),p="Assets/Afrer_Seconds/05.Model/Props/B5/";var s=SceneManager.GetActiveScene();var bank=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("C01_Experiment_Art/C01_Perimeter_Lab");
 var before=JObject.Parse(File.ReadAllText(root+"/SourceAssets/C01_InstrumentDetail/placement.json"))["after"];var after=JObject.FromObject(bank.Cast<Transform>().Where(t=>t.name.StartsWith("Station_")).ToDictionary(t=>t.name,t=>new{position=t.localPosition.ToString("F5"),rotation=t.localEulerAngles.ToString("F5")}));bool stations=JToken.DeepEquals(before,after);
 var mats=new List<object>();bool ok=true;foreach(string f in new[]{"Coat","Blue","Steel","Dark","Rubber","Paper"}){var m=AssetDatabase.LoadAssetAtPath<Material>(p+"Materials/CP_"+f+".mat");bool valid=m.GetTexture("_BaseMap")&&m.GetTexture("_BumpMap")&&m.GetTexture("_MetallicGlossMap")&&m.IsKeywordEnabled("_NORMALMAP")&&m.IsKeywordEnabled("_METALLICSPECGLOSSMAP");ok&=valid;mats.Add(new{name=m.name,valid,baseMap=AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap")),normal=AssetDatabase.GetAssetPath(m.GetTexture("_BumpMap")),packed=AssetDatabase.GetAssetPath(m.GetTexture("_MetallicGlossMap")),tiling=m.GetTextureScale("_BaseMap").ToString()});}
 var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player")).transform;var result=new{accepted30StationTransformsPreserved=stations,pbrMaterialsValid=ok,materials=mats,sceneDirty=s.isDirty,playing=Application.isPlaying,playerPosition=player.position.ToString("F3"),playerRotation=player.eulerAngles.ToString("F3")};File.WriteAllText(root+"/Docs/검수/2026-11-07_C01_PropRepair/state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object ImportProvenance(){string p="Assets/Afrer_Seconds/06.Data/AssetSources/C01_PropRepair_20261107.json";AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);return new{path=p,guid=AssetDatabase.AssetPathToGUID(p),sceneDirty=SceneManager.GetActiveScene().isDirty};}
}
